import type { HTMLAttributes } from "svelte/elements";

import type {} from "../register-types/html-element.ts";
import type { CustomElements } from "../register-types/svelte-elements.d.ts";

/**
 * The props generated by `custom-element-svelte-integration`, alongside the
 * attributes and event handlers Svelte accepts on every HTML element
 */
type SvelteCustomElements = {
  [Tag in keyof CustomElements]: HTMLAttributes<HTMLElementTagNameMap[Tag]> & CustomElements[Tag];
};

// `custom-element-svelte-integration` declares its `svelteHTML` namespace
// within a module, where it doesn't merge with Svelte's global declaration, so
// its types are registered with `svelte/elements` here instead
declare module "svelte/elements" {
  interface SvelteHTMLElements extends SvelteCustomElements {}
}
